using DevInn.Application.Features.Financial.Expenses.CreateExpense;using DevInn.WebApi.Common;using Mediator;namespace DevInn.WebApi.Endpoints.Financial.Expenses;public sealed class CreateExpenseEndpoint : IEndpoint{    private const string Route = "api/v1/expenses";    public void MapEndpoint(IEndpointRouteBuilder app)    {        app.MapPost(Route, async (CreateExpenseCommand command, ISender sender, CancellationToken ct) =>            {                var result = await sender.Send(command, ct);                return result.ToCreated(id => $"{Route}/{id}");            })            .WithTags(Tags.Expenses)            .WithName("Create Expense")            .Produces<ApiResource<Guid>>(StatusCodes.Status201Created)            .Produces<ApiProblemDetails>(StatusCodes.Status400BadRequest)            .Produces<ApiProblemDetails>(StatusCodes.Status422UnprocessableEntity)            .RequireAuthorization();    }}